# qx_chunk :: ([1, 2, 3, 4, 5, 6, 7, 8, 9], 3)
def qx_chunk(xs, n):
    if n <= 0: return []
    return [xs[i:i+n] for i in range(0, len(xs), n)]

if __name__ == '__main__':
    print(qx_chunk(([1, 2, 3, 4, 5, 6, 7, 8, 9], 3)))

